package com.example.quickstart;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.graphics.Color;import android.graphics.Typeface;import android.view.Gravity;import android.view.View;import android.widget.*;

public class HomeActivity extends Activity {
 @Override protected void onCreate(Bundle b){super.onCreate(b);String name=getSharedPreferences("account",MODE_PRIVATE).getString("name","there");LinearLayout root=Ui.page(this,"Hello, "+name+" 👋","What would you like to explore today?");
 LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setOrientation(LinearLayout.HORIZONTAL);TextView hint=Ui.text(this,"Your dashboard",18,true,Ui.DARK);top.addView(hint,new LinearLayout.LayoutParams(0,Ui.dp(this,44),1));TextView profile=Ui.text(this,"👤 Profile",14,true,Ui.PURPLE);profile.setPadding(12,8,12,8);profile.setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));top.addView(profile);root.addView(top);
 GridLayout grid=new GridLayout(this);grid.setColumnCount(2);grid.setUseDefaultMargins(true);String[][] items={{"📚","My Learning","Browse your learning"},{"📅","Calendar","Plan your day"},{"✅","Tasks","Keep track of tasks"},{"📊","Progress","See your progress"},{"💬","Messages","Stay connected"},{"⚙️","Settings","Manage preferences"}};
 for(String[] item:items){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(Ui.dp(this,16),Ui.dp(this,18),Ui.dp(this,12),Ui.dp(this,16));card.setBackground(Ui.round(Color.WHITE,Ui.dp(this,16),Color.rgb(232,231,242)));GridLayout.LayoutParams cp=new GridLayout.LayoutParams();cp.width=0;cp.height=Ui.dp(this,142);cp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);cp.setMargins(Ui.dp(this,4),Ui.dp(this,5),Ui.dp(this,4),Ui.dp(this,5));TextView icon=Ui.text(this,item[0],30,false,Ui.DARK);TextView title=Ui.text(this,item[1],17,true,Ui.DARK);TextView desc=Ui.text(this,item[2],12,false,Ui.GREY);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.topMargin=Ui.dp(this,8);card.addView(icon);card.addView(title,tp);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,-2);dp.topMargin=Ui.dp(this,3);card.addView(desc,dp);card.setOnClickListener(v->Ui.toast(this,item[1]+" selected"));grid.addView(card,cp);}
 root.addView(grid);root.addView(Ui.button(this,"View profile",()->startActivity(new Intent(this,ProfileActivity.class))));root.addView(Ui.link(this,"Log out",()->{Intent i=new Intent(this,LoginActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);finish();})); }
}
